-- 7. Réalignement des séquences d'incrémentation
SELECT setval('public.users_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.users));
SELECT setval('public.articles_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.articles));
SELECT setval('public.comments_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.comments));

-- 8. Vérification
SELECT count(*) as total_utilisateurs FROM public.users;
SELECT count(*) as total_articles FROM public.articles;
